window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["structured-output"]={"title":"结构化输出：把概率文本接入确定性软件契约","subtitle":"从最小 schema、约束生成和分层校验，到版本迁移、有限修复与安全执行。","thesis":"结构化输出把模型回答转换为可解析、可校验、可版本化的数据契约。可靠链路不是“看起来像 JSON”，而是<b>生成时约束、完整性判断、schema 校验、业务/事实校验、执行时鉴权</b>；任何前一层通过都不能替代后一层。","quality":{"contractVersion":2,"examples":[{"section":4,"evidence":{"setup":"amount=120","rule":"最多可退 80","steps":"可退上限 ¥80","interpretation":"不能静默截成 80 执行"}}],"formulas":[{"id":"structured-output-refundable","section":4,"formulaIndex":1,"symbols":[{"name":"R","meaning":"订单当前最多可退金额","evidence":"R 是本订单当前最多可退金额"},{"name":"P","meaning":"订单实付金额","evidence":"P 是订单实付金额"},{"name":"D","meaning":"此前已退款金额","evidence":"D 是此前已退款金额"},{"name":"L","meaning":"政策允许的金额上限","evidence":"L 是政策允许的金额上限"},{"name":"min","meaning":"取候选上限中的较小值","evidence":"取两个候选上限中较小者"}]},{"id":"structured-output-constrained-proportional","section":5,"formulaIndex":1,"symbols":[{"name":"P","meaning":"原始或约束后的 token 概率","evidence":"原始 token t 的概率"},{"name":"t","meaning":"当前候选 token","evidence":"token t 的概率"},{"name":"s","meaning":"当前解析状态","evidence":"状态 s"},{"name":"M","meaning":"当前合法 token 集","evidence":"当前仍合法的 token 集"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"结构化输出把模型回答变成可解析、校验、拒绝和版本化的数据对象。","evidence":"结构化输出输入任务语义和版本化数据契约"},"problem":{"answer":"它解决自然语言变体对程序接口造成解析和状态歧义的问题。","evidence":"为什么人能理解而程序会崩"},"inputOutput":{"answer":"输入任务语义与契约，输出可解析校验且可拒绝的对象。","evidence":"输出可解析、可校验并可被程序拒绝的对象"},"mechanism":{"answer":"schema、约束生成和解析器把字段类型边界变成机械检查。","evidence":"把自然语言容错转成明确字段和状态"},"interpretation":{"answer":"格式有效只表示机器能读，不表示内容真实。","evidence":"格式有效只表示机器能读取"},"boundary":{"answer":"结构化对象仍不能自动获得执行权限。","evidence":"不表示对象内容可信或允许执行"}},{"section":2,"definition":{"answer":"四道门依次验证完整语法、schema、业务事实和权限副作用。","evidence":"四道门必须逐层通过"},"problem":{"answer":"它说明 JSON 可解析距离安全执行退款还差哪些检查。","evidence":"离执行退款还差多远"},"inputOutput":{"answer":"输入模型对象、schema、业务数据和主体，输出通过、错误或升级。","evidence":"输出通过、字段错误、补信息、拒绝或升级"},"mechanism":{"answer":"按语法、形状、事实关系、身份权限的顺序逐层检查。","evidence":"依次检查完整语法、schema、业务事实和权限副作用"},"interpretation":{"answer":"前一门通过只表示该层合格，不能替代后一层。","evidence":"前一层通过不能替代后一层"},"boundary":{"answer":"任何一层失败都必须阻断执行，不允许下游猜测。","evidence":"任何失败都禁止下游猜测执行"}},{"section":3,"definition":{"answer":"最小 schema 只要求模型生成必须进行语义判断的字段。","evidence":"最小 schema 比大而全更可靠"},"problem":{"answer":"它减少大对象的无效路径、消费者耦合和版本迁移风险。","evidence":"为什么会提高错误率和耦合"},"inputOutput":{"answer":"输入业务决策字段和兼容要求，输出最小字段及显式分支。","evidence":"输出只含模型必须判断的字段与显式分支"},"mechanism":{"answer":"服务器填权威派生值，枚举与 discriminated union 拆小任务。","evidence":"服务器填身份、时间和派生值"},"interpretation":{"answer":"字段更少表示模型责任更窄，不表示业务信息被删除。","evidence":"只让模型产生需要语义判断的字段"},"boundary":{"answer":"过度嵌套会增加状态空间、无效路径与迁移成本。","evidence":"过度嵌套会增加无效路径、版本耦合和迁移成本"}},{"section":4,"definition":{"answer":"本案例展示语法和 schema 合法的退款对象仍可在事实与权限层失败。","evidence":"合法对象如何在后两层失败"},"problem":{"answer":"它解释 amount 120 在通用范围内却不能安全执行的原因。","evidence":"为什么仍不能执行"},"inputOutput":{"answer":"输入对象、订单政策和角色，输出业务错误码或安全动作。","evidence":"输出业务错误码或安全动作"},"mechanism":{"answer":"用实付、已退和政策上限计算实际可退额，再检查批准权限。","evidence":"公式算得最多可退 80"},"interpretation":{"answer":"schema 的 0 到 500 只表示通用形状范围，不代表订单可退额。","evidence":"违反订单不变量"},"boundary":{"answer":"不能静默把 120 改成 80 执行，须解释或转人工。","evidence":"不能静默截成 80 执行"}},{"section":5,"definition":{"answer":"生成时约束和生成后校验分别减少无效路径与捕获语义错误。","evidence":"约束生成与生成后校验是互补的"},"problem":{"answer":"它解释服务端会校验时为何仍值得在生成阶段约束。","evidence":"为什么还要生成时约束"},"inputOutput":{"answer":"输入模型分布、schema 与业务规则，输出受约束且复验的对象。","evidence":"输出格式受约束且经后验验证的对象"},"mechanism":{"answer":"生成时掩码非法 token，生成后检查实现、版本和语义。","evidence":"生成时掩码减少无效重试"},"interpretation":{"answer":"结构通过率上升不保证业务正确率或任务质量也上升。","evidence":"不能只庆祝结构通过率"},"boundary":{"answer":"自动修复仅适合纯语法且能证明语义等价的情况。","evidence":"只有纯语法且可证明等价的修复"}},{"section":6,"definition":{"answer":"失败恢复按失败层选择局部、有限且无副作用的下一动作。","evidence":"失败恢复要局部、有限且无副作用"},"problem":{"answer":"它避免无限重试增加延迟、注入面和重复执行风险。","evidence":"无限重试会发生什么"},"inputOutput":{"answer":"输入字段路径错误码范围和幂等键，输出修复、澄清、拒绝或升级。","evidence":"输出局部修复、澄清、重取事实、拒绝或人工升级"},"mechanism":{"answer":"针对错误类型有限重试，校验通过前绝不执行副作用。","evidence":"重试次数必须有限"},"interpretation":{"answer":"连续同类失败表示当前 schema 或任务路径不适合继续生成。","evidence":"同类连续失败应降级"},"boundary":{"answer":"校验完成前不得产生副作用，执行重试还须复用幂等键。","evidence":"校验前不产生副作用"}},{"section":7,"definition":{"answer":"schema 版本演进是生产者与所有消费者共同参与的分布式契约迁移。","evidence":"版本演进是一项分布式契约"},"problem":{"answer":"它防止新字段或枚举让旧消费者拒绝或静默误执行。","evidence":"旧消费者为什么可能静默误读"},"inputOutput":{"answer":"输入新旧 schema、组件版本和 trace，输出兼容矩阵与迁移计划。","evidence":"输出兼容矩阵与 expand/contract 发布计划"},"mechanism":{"answer":"先更新消费者兼容新旧，再切生产者，最后退役旧契约。","evidence":"先让消费者接受新旧"},"interpretation":{"answer":"新增语法项不自动等于向后兼容，需按消费者行为判断。","evidence":"不能仅按“新增”判断兼容"},"boundary":{"answer":"提示、schema、编译器和消费者版本必须一起记录回放。","evidence":"回放旧 trace 才能复现当时规则"}},{"section":8,"definition":{"answer":"安全执行用认证主体、工具白名单、策略与审批重新验证合法参数。","evidence":"安全执行不信任模型提供的身份与工具名"},"problem":{"answer":"它防止提示注入诱导模型选择语法允许但不合适的动作或金额。","evidence":"为什么提示注入仍可能造成伤害"},"inputOutput":{"answer":"输入合法参数和权威安全状态，输出最小权限执行或拒绝。","evidence":"输出以最小权限执行或拒绝"},"mechanism":{"answer":"服务器重取认证身份并校验对象、金额、工具、速率和审批。","evidence":"服务器重新鉴权并限制金额与对象"},"interpretation":{"answer":"schema 合法只限制形状，字符串中仍可能携带攻击载荷。","evidence":"结构化字符串仍可携带注入载荷"},"boundary":{"answer":"模型不能继承服务账号权限，每次工具调用都要重新鉴权。","evidence":"每次工具调用都以最小权限和当前主体重新鉴权"}},{"section":9,"definition":{"answer":"端到端契约评测沿生成、校验、执行和业务后果逐层定位失败。","evidence":"评测应沿整条契约定位失败"},"problem":{"answer":"它补足结构化输出成功率无法反映事实、权限与副作用的缺陷。","evidence":"还缺哪些能决定上线的数字"},"inputOutput":{"answer":"输入输出、日志、工具结果和后果，输出多层质量、延迟和成本指标。","evidence":"输出语法、schema、字段、事实、权限、幂等、任务质量、延迟与成本指标"},"mechanism":{"answer":"先查完整，再查形状、事实关系和当前主体能否执行。","evidence":"先问输出是否完整"},"interpretation":{"answer":"最终损失决定错误严重性，不能把越权与无害重试等权平均。","evidence":"错误预算按最终损失分级"},"boundary":{"answer":"单次越权必须设独立硬门和即时回滚，不能被平均成功率抵消。","evidence":"不能被大量无害格式成功平均掉"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分语法/schema/语义/权限；设计最小可演进 schema；演算字段校验与修复；安全连接工具和数据库。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>自然语言和程序接口的容错方式不同<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">多一句“好的”或少一个引号，为什么人能理解而程序会崩？</p><p>结构化输出输入任务语义和版本化数据契约，输出可解析、可校验并可被程序拒绝的对象。生成约束与解析器把自然语言容错转成明确字段和状态；格式有效只表示机器能读取，不表示对象内容可信或允许执行。</p><p>自然语言依靠语境容忍变体，程序需要明确边界、类型与状态。结构化输出声明字段、必填、枚举、长度和版本，使消费者能机械拒绝异常，而不是用脆弱正则猜模型意图。</p><p>提示“返回 JSON”只提高概率；JSON mode 通常保语法；JSON Schema 才进一步约束形状；约束解码在生成时阻止非法路径。支持范围依实现而异，仍需服务端复验。</p><div class=\"dd-note\"><b>数据契约的作用：</b>让失败显式、局部、可计数。它不把概率模型变成可信数据库。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>四道门必须逐层通过<span class=\"dd-badge eng\">分层</span></h2><p class=\"dd-lead\">一个对象能被 JSON.parse 解析，离执行退款还差多远？</p><p>分层验证输入模型对象、schema、权威业务数据与当前主体，输出通过、字段错误、补信息、拒绝或升级。依次检查完整语法、schema、业务事实和权限副作用；前一层通过不能替代后一层，任何失败都禁止下游猜测执行。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层</th><th>检查</th><th>例子</th><th>失败处理</th></tr></thead><tbody><tr><td>完整语法</td><td>括号、引号、转义、结束态</td><td>不是半截 JSON</td><td>拒绝/重生</td></tr><tr><td>Schema</td><td>字段、类型、枚举、范围</td><td>action∈refund/ask</td><td>字段级错误</td></tr><tr><td>业务与事实</td><td>跨字段规则、查库、证据</td><td>amount≤订单可退额</td><td>补信息/转人工</td></tr><tr><td>权限与副作用</td><td>主体、策略、幂等、审批</td><td>当前客服能否批准</td><td>禁止或升级</td></tr></tbody></table></div><p>任何一层失败都不应让下游“尽量猜”。特别是模型给出的 user_id、金额和 action 都是不可信建议，执行层必须从认证上下文重新取得主体与权限。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>最小 schema 比大而全更可靠<span class=\"dd-badge eng\">设计</span></h2><p class=\"dd-lead\">把所有可能字段都塞进一个嵌套对象，为什么会提高错误率和耦合？</p><p>最小 schema 设计输入业务决策字段、服务器已有事实和兼容要求，输出只含模型必须判断的字段与显式分支。服务器填身份、时间和派生值，枚举和 discriminated union 缩小状态空间；过度嵌套会增加无效路径、版本耦合和迁移成本。</p><p>只让模型产生需要语义判断的字段；时间戳、用户 ID、总价和派生状态由服务器填充。枚举代替自由动作名，明确 missing 与 null，限制字符串/数组长度，默认拒绝 additionalProperties，并给每个字段写业务含义与例子。</p><p>把互斥任务拆成 discriminated union：先用 <code>kind</code> 选择 refund_request 或 ask_clarification，再使用对应的小 schema。这样比一个包含几十个可选字段的对象更容易约束、校验和迁移。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>设计选择</th><th>收益</th><th>风险</th></tr></thead><tbody><tr><td>枚举动作</td><td>消费者无需猜拼写</td><td>新增值需兼容</td></tr><tr><td>必填字段</td><td>状态完整</td><td>未知值不要用假默认</td></tr><tr><td>长度/范围</td><td>限制资源与荒谬值</td><td>边界需与业务同步</td></tr><tr><td>禁止额外字段</td><td>发现 schema 漂移</td><td>前后版本需协商</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>运行示例：合法对象如何在后两层失败<span class=\"dd-badge math\">案例推演</span></h2><p class=\"dd-lead\">模型输出 action=refund、amount=120，语法和 schema 都正确，为什么仍不能执行？</p><p>案例输入结构合法对象、订单实付与退款记录、政策上限和当前角色，输出业务错误码或安全动作。公式算得最多可退 80，因此 120 违反订单不变量且角色无批准权；不能静默截成 80 执行，因为那会改变模型意图并掩盖上游错误。</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 710 260\" role=\"img\" aria-label=\"退款结构化输出经过语法、schema、业务事实和权限四道验证门\"><defs><marker id=\"so1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><rect x=\"16\" y=\"85\" width=\"135\" height=\"88\" rx=\"8\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"83\" y=\"109\" text-anchor=\"middle\" class=\"svg-t\">模型对象</text><text x=\"83\" y=\"131\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">action=refund</text><text x=\"83\" y=\"150\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">amount=120</text><path d=\"M151,129 L188,129\" stroke=\"#6b7484\" marker-end=\"url(#so1)\"/><rect x=\"190\" y=\"85\" width=\"112\" height=\"88\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"246\" y=\"110\" text-anchor=\"middle\" class=\"svg-t\">语法 ✓</text><text x=\"246\" y=\"132\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">完整 JSON</text><text x=\"246\" y=\"151\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">无截断</text><path d=\"M302,129 L339,129\" stroke=\"#6b7484\" marker-end=\"url(#so1)\"/><rect x=\"341\" y=\"85\" width=\"112\" height=\"88\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"397\" y=\"110\" text-anchor=\"middle\" class=\"svg-t\">Schema ✓</text><text x=\"397\" y=\"132\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">枚举合法</text><text x=\"397\" y=\"151\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">0≤amount≤500</text><path d=\"M453,129 L490,129\" stroke=\"#6b7484\" marker-end=\"url(#so1)\"/><rect x=\"492\" y=\"57\" width=\"196\" height=\"70\" rx=\"8\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"590\" y=\"82\" text-anchor=\"middle\" class=\"svg-t\">业务/事实 ✕</text><text x=\"590\" y=\"104\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">订单实付 ¥80，可退上限 ¥80</text><rect x=\"492\" y=\"145\" width=\"196\" height=\"70\" rx=\"8\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"590\" y=\"170\" text-anchor=\"middle\" class=\"svg-t\">权限 ✕</text><text x=\"590\" y=\"192\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">当前角色只能建议，不能批准</text><path d=\"M590,127 L590,143\" stroke=\"#6b7484\" marker-end=\"url(#so1)\"/></svg><figcaption>图 1　格式保证只让错误更容易检测；数据库事实和当前主体权限仍决定能否执行。</figcaption></figure><div class=\"dd-formula\" data-formula-id=\"structured-output-refundable\"><math display=\"block\" aria-label=\"可退金额 R 等于实付金额 P 减已退款金额 D 与政策上限 L 两者中的最小值，本例为八十\"><mrow><mi>R</mi><mo>=</mo><mi>min</mi><mo>(</mo><mi>P</mi><mo>−</mo><mi>D</mi><mo>,</mo><mi>L</mi><mo>)</mo><mo>=</mo><mi>min</mi><mo>(</mo><mn>80</mn><mo>−</mo><mn>0</mn><mo>,</mo><mn>100</mn><mo>)</mo><mo>=</mo><mn>80</mn></mrow></math></div><p class=\"dd-formula-note\"><code>R</code> 是本订单当前最多可退金额，<code>P</code> 是订单实付金额，<code>D</code> 是此前已退款金额，<code>L</code> 是政策允许的金额上限，<code>min</code> 表示取两个候选上限中较小者。该业务不变量依赖权威订单和政策数据，不能只靠 schema 的通用范围判断。</p><p>amount=120 在 schema 的通用 0–500 范围内，却违反订单不变量。正确恢复是返回 <code>amount_exceeds_remaining</code>，让模型改为解释或转人工；不是偷偷把 120 截成 80 后执行，因为这改变了原意且可能掩盖上游错误。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>约束生成与生成后校验是互补的<span class=\"dd-badge math\">机制</span></h2><p class=\"dd-lead\">如果服务端最终都会校验，为什么还要生成时约束？</p><p>双层机制输入模型分布、schema 和服务端业务规则，输出格式受约束且经后验验证的对象。生成时掩码减少无效重试，生成后校验捕获实现错配与语义错误；格式成功但业务质量下降时不能只庆祝结构通过率。</p><p>约束解码减少语法/schema 无效输出和无效重试；服务端校验防实现缺陷、版本错配和语义错误。受限采样把非法 token 置零并重新归一化：</p><div class=\"dd-formula\" data-formula-id=\"structured-output-constrained-proportional\"><math display=\"block\" aria-label=\"状态 s 下 token t 的受限概率 P prime 与原概率 P 乘合法集合指示函数成正比\"><mrow><msup><mi>P</mi><mo>′</mo></msup><mo>(</mo><mi>t</mi><mo>∣</mo><mi>s</mi><mo>)</mo><mo>∝</mo><mi>P</mi><mo>(</mo><mi>t</mi><mo>∣</mo><mi>s</mi><mo>)</mo><mn>1</mn><mo>[</mo><mi>t</mi><mo>∈</mo><mi>M</mi><mo>(</mo><mi>s</mi><mo>)</mo><mo>]</mo></mrow></math></div><p class=\"dd-formula-note\"><code>P(t|s)</code> 是状态 s 下原始 token t 的概率，<code>P′(t|s)</code> 是应用约束后的概率，<code>M(s)</code> 是当前仍合法的 token 集，<code>1[·]</code> 是合法取 1、非法取 0 的指示函数，符号 ∝ 表示右侧还需除以全部合法候选的概率总和才能归一化。</p><p>当模型原本大部分概率压在非法候选上，约束会迫使它选择低概率合法值，格式成功却可能内容变差。因此要同时看首次结构通过率、业务正确率和任务质量。若底层 API 不支持某些 schema 特性，应在启动时契约测试并生成后复验，而非默认相信声明。</p><div class=\"dd-note warn\"><b>不要用自动修复掩盖分布问题。</b>　“修 JSON”模型可能改变字段含义；只有纯语法且可证明等价的修复才适合自动应用。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>失败恢复要局部、有限且无副作用<span class=\"dd-badge eng\">可靠性</span></h2><p class=\"dd-lead\">校验失败后，把整个错误对象原样塞回模型无限重试会发生什么？</p><p>失败恢复输入机器生成的字段路径、错误代码、允许范围与请求幂等键，输出局部修复、澄清、重取事实、拒绝或人工升级。重试次数必须有限，校验前不产生副作用；同类连续失败应降级到更简单 schema 或确定性表单。</p><p>会增加延迟、成本、提示注入面和重复动作。返回机器生成的字段路径、错误代码与允许范围，不回显不可信大段文本；限制重试次数。第一次校验前绝不执行副作用，重试复用请求 ID 和幂等键。</p><ol class=\"dd-steps\"><li>纯语法失败：约束重生或一次修复。</li><li>缺必填且可向用户询问：返回 ask_clarification。</li><li>事实/业务冲突：重新取权威数据，不让模型猜。</li><li>权限不足：禁止执行，必要时升级人工。</li><li>同类连续失败：降级更简单 schema 或确定性表单。</li></ol><p>记录首次通过率、每字段错误、修复后通过、最终任务失败、重试次数和额外 p95。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>版本演进是一项分布式契约<span class=\"dd-badge eng\">版本</span></h2><p class=\"dd-lead\">生产者升级 schema 后，旧消费者为什么可能静默误读？</p><p>契约迁移输入旧新 schema、生产者消费者版本和历史 trace，输出兼容矩阵与 expand/contract 发布计划。先让消费者接受新旧，再让生产者发送新，最后退役旧；新增枚举和严格额外字段都可能破坏旧逻辑，不能仅按“新增”判断兼容。</p><p>schema 需要版本号和兼容政策。新增可选字段通常向后兼容，但消费者若拒绝额外字段则不是；新增枚举值会让旧 switch 落入错误默认分支；删除/改类型是破坏性变化。采用 expand/contract：先让消费者接受新旧，再让生产者发送新，最后移除旧。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>变更</th><th>典型风险</th><th>迁移</th></tr></thead><tbody><tr><td>新增可选字段</td><td>严格消费者拒绝</td><td>先更新消费者</td></tr><tr><td>新增枚举值</td><td>未知值误执行</td><td>显式 unknown 分支</td></tr><tr><td>字段改名/类型</td><td>破坏读写</td><td>双写/双读后退役</td></tr><tr><td>收紧范围</td><td>旧数据不再合法</td><td>迁移数据并分版本校验</td></tr></tbody></table></div><p>提示、schema、约束编译器和消费者版本要一起记录；回放旧 trace 才能复现当时规则。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>安全执行不信任模型提供的身份与工具名<span class=\"dd-badge eng\">安全</span></h2><p class=\"dd-lead\">schema 已把 action 限定为 refund，为什么提示注入仍可能造成伤害？</p><p>安全执行输入合法参数、认证主体、工具白名单、策略与审批状态，输出以最小权限执行或拒绝。模型提供的身份、工具名和自由文本都不可信，服务器重新鉴权并限制金额与对象；结构化字符串仍可携带注入载荷，消费者必须按目标上下文转义。</p><p>攻击者可诱导模型选择语法允许但不合适的动作或金额。工具注册表只暴露当前流程允许的能力；服务器从会话认证取得 user/tenant，不接受模型自报；参数做对象级授权、速率、金额、目的与审批校验。高风险动作先生成计划，由确定性策略门和人工确认后提交。</p><p>自由文本字段可能携带 SQL、HTML 或给下一个 agent 的注入，消费者必须按上下文转义并标记不可信。结构化不等于净化；它只是把攻击载荷放进了一个合法字符串。</p><div class=\"dd-note warn\"><b>Confused deputy：</b>模型可以代表用户建议动作，但不能继承服务账号全部权限。每次工具调用都以最小权限和当前主体重新鉴权。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>评测应沿整条契约定位失败<span class=\"dd-badge intuition\">评测</span></h2><p class=\"dd-lead\">“结构化输出成功率 99.9%”还缺哪些能决定上线的数字？</p><p>端到端评测输入模型输出、验证日志、工具结果和业务后果，输出语法、schema、字段、事实、权限、幂等、任务质量、延迟与成本指标。错误预算按最终损失分级，单次越权不能被大量无害格式成功平均掉。</p><p>按层报告：完整语法率、schema 首次通过、死路、字段级错误、业务/事实通过、权限拦截、工具成功、重复副作用、最终任务质量、额外延迟和成本。用断流、Unicode、超长数组、未知枚举、旧消费者、新政策和恶意自由文本回归。</p><p>错误预算要基于最终后果。大量无害格式重试和一次越权退款不能被同一平均失败率对待；后者设独立硬门槛和即时回滚。</p><div class=\"dd-note\"><b>诊断顺序：</b>先问输出是否完整，再问形状是否正确，再问事实/关系是否成立，最后问当前主体是否能安全执行。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与概念依赖<span class=\"dd-badge intuition\">常见误区与学习路线</span></h2><p class=\"dd-lead\">结构化输出的价值是建立可拒绝的边界，而不是让模型输出天然可信。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>JSON mode 等于 schema</td><td>前者常只保证语法，后者约束字段和类型</td></tr><tr><td>schema 通过等于内容正确</td><td>事实和跨字段不变量需外部验证</td></tr><tr><td>自动修复总比失败好</td><td>修复可能改语义，应有限且可证明</td></tr><tr><td>加字段总是兼容</td><td>严格消费者和枚举分支可能破坏</td></tr><tr><td>合法参数就有权执行</td><td>执行层仍需主体鉴权、策略和幂等</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸学习</th></tr></thead><tbody><tr><td>先修</td><td>JSON/Schema、tokenization、API 契约</td></tr><tr><td><b>本页核心</b></td><td>最小 schema、分层验证、恢复、版本迁移</td></tr><tr><td>生成机制</td><td>约束解码、采样参数、流式输出</td></tr><tr><td>执行安全</td><td>工具调用、身份权限、工作流编排与应用评测</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">11</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>定义最小版本化 schema</li><li>生成时约束并等待完整接受态</li><li>服务端重新解析与 schema 校验</li><li>验证事实和跨字段业务不变量</li><li>以当前主体鉴权后幂等执行</li><li>按失败层记录并有限恢复/回滚</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">12</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>JSON 语法通过与 schema 通过差什么？</li><li>amount=120 为什么示例中不能执行？</li><li>为什么约束生成后仍要校验？</li><li>新增枚举为何可能破坏旧消费者？</li><li>失败重试如何避免重复退款？</li><li>假设“结构化输出：把概率文本接入确定性软件契约”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>前者只保证可解析，后者还检查字段、类型、枚举和范围。</li><li>虽在通用范围内，但订单剩余可退额只有 80，且当前角色无批准权限。</li><li>防实现/版本错配，并处理业务、事实和权限等文法无法表达的条件。</li><li>旧 switch 可能没有安全 unknown 分支。</li><li>校验全部通过前不执行，执行与重试使用同一幂等键。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://json-schema.org/specification\" target=\"_blank\" rel=\"noopener\">JSON Schema Specification</a>：JSON 数据契约与验证语义</li><li><a href=\"https://arxiv.org/abs/2109.05093\" target=\"_blank\" rel=\"noopener\">PICARD</a>：生成过程中拒绝非法 token</li><li><a href=\"https://arxiv.org/abs/2501.10868\" target=\"_blank\" rel=\"noopener\">JSONSchemaBench</a>：约束解码覆盖与效率评测</li><li><a href=\"https://owasp.org/API-Security/\" target=\"_blank\" rel=\"noopener\">OWASP API Security Top 10</a>：对象授权、资源与接口安全边界</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
